import squizStoryRenderer from '@ntgovernment/squiz-factory/plugins/squizStoryRenderer';
import './footer.css';
import comp from './main.js';
import defaultArgs from './previews/default.data.json';

const squiz = squizStoryRenderer(comp.main);

export default {
  title: 'dxp components/Footer',
  parameters: {
    layout: 'fullscreen',
  },
};

const defaultHtml = await squiz.markup(defaultArgs); 

export const Default = {
  render: (args) => {
    requestAnimationFrame(supressClick);
    return squiz(args);
  },
  args: defaultArgs,
  argTypes: {
    menus: { control: 'object' },
    ancillary: { control: 'object' },
    finalText: { control: 'text' },
  },
  parameters: {
    docs: {
      source: { code: defaultHtml, language: 'html', type: 'code' },
    },
  },
};

function supressClick() {
  document.body.removeEventListener('click', handleSupressClick);
  document.body.addEventListener('click', handleSupressClick);
}
function handleSupressClick(e) { e.preventDefault(); }